import Foundation

@MainActor func runExamSourceTests() async -> Int {
    var checks = 0
    func expect(_ condition: @autoclosure () -> Bool, _ message: String) {
        guard condition() else { fputs("EXAM_SOURCE_TEST_FAILED: \(message)\n", stderr); exit(1) }; checks += 1
    }
    expect(ExamLibrary.materials.count == 8 && ExamLibrary.materials.allSatisfy(\.valid), "bundled catalog contains eight validated reference entries")
    expect(ExamLibrary.materials.filter { $0.evidence == .pastPaper }.count == 3, "three short CET excerpts have verified source locations")
    expect(ExamLibrary.materials.filter { $0.evidence == .officialSample }.count == 5, "IELTS entries explicitly identify official samples")
    var preferences = Preferences()
    let legacyPreferenceData = try! JSONEncoder().encode(preferences)
    let oldPreferences = try! JSONDecoder().decode(Preferences.self, from: legacyPreferenceData)
    expect(oldPreferences.effectiveExamTrack == .mixed && oldPreferences.examTrack == nil, "old preferences decode without a new required field")
    let directions: [Direction] = [.zhToEn, .enToZh, .zhToEn, .enToZh]
    let plan = ExamLibrary.plan(preferences: preferences, directions: directions, avoiding: [])
    expect(plan.map(\.kind) == [.excerpt, .adapted, .original, .adapted], "mixed batch combines verified text, adaptations and original imitations")
    let generated = [GeneratedSentence(slot: 1, source: "Changes in traffic speed can sometimes lead to serious congestion.", direction: .enToZh, focus: "因果关系"), GeneratedSentence(slot: 2, source: "学校应鼓励学生在实践中独立解决问题。", direction: .zhToEn, focus: "建议与实践"), GeneratedSentence(slot: 3, source: "More adults now combine part-time study with their full-time jobs.", direction: .enToZh, focus: "对照与兼顾")]
    let values = try! ExamLibrary.assemble(plan: plan, generated: generated, preferences: preferences, model: "test-model")
    expect(values.count == 4 && values.allSatisfy { $0.verifiedProvenance != nil }, "all generated slots carry locally verified provenance")
    expect(values[0].source == plan[0].material?.excerpt && values[0].model == "本机核验材料", "genuine excerpt is copied locally and never regenerated by the model")
    expect(values[1].provenance?.materialID == plan[1].material?.id && values[2].provenance?.materialID == nil, "only adaptations receive the actual supplied reference ID")
    expect(values[2].citationURL == nil && values[2].sourceDescription.contains("不是"), "original imitations have no invented historical citation")
    expect(values[1].sourceDescription.contains("官方样题") && values[1].sourceDescription.contains("不是"), "IELTS adaptations never claim historical translation questions")
    var altered = values[0]; altered.source += "新"
    expect(altered.verifiedProvenance == nil && altered.citationURL == nil, "changed characters invalidate an excerpt claim")
    altered = values[0]; altered.direction = .enToZh
    expect(altered.verifiedProvenance == nil, "a translated or wrong-direction sentence cannot remain a genuine excerpt")
    altered = values[0]; altered.provenance?.materialID = "fabricated-2026-paper"
    expect(altered.verifiedProvenance == nil && altered.sourceBadge == "来源未核实", "unknown reference IDs cannot display as verified")
    altered = values[1]; altered.provenance?.kind = .excerpt
    expect(altered.verifiedProvenance == nil, "an official IELTS sample cannot be presented as a past-paper excerpt")
    altered = values[0]; altered.provenance = ExerciseProvenance(kind: .original, track: .cet6)
    expect(altered.verifiedProvenance == nil, "known verbatim exam text cannot be mislabeled as original")
    altered = values[2]; altered.provenance?.materialID = plan[0].material?.id
    expect(altered.verifiedProvenance == nil, "an original imitation cannot attach a fake reference")
    var legacy = values[2]; legacy.provenance = nil
    let oldExercise = try! JSONDecoder().decode(Exercise.self, from: JSONEncoder().encode(legacy))
    expect(oldExercise.provenance == nil && oldExercise.sourceBadge == "来源未标注" && oldExercise.citationURL == nil, "legacy exercises retain unknown provenance rather than receiving guessed labels")
    let reloaded = try! JSONDecoder().decode([Exercise].self, from: JSONEncoder().encode(values))
    expect(reloaded == values, "source proof persists with exercise and historical record")
    let allExcerpts = ExamLibrary.materials.compactMap(\.excerpt)
    expect(ExamLibrary.plan(preferences: preferences, directions: directions, avoiding: allExcerpts).allSatisfy { $0.kind != .excerpt }, "previously seen verified excerpts are not repeatedly served")
    preferences.examTrack = .ielts
    let ieltsPlan = ExamLibrary.plan(preferences: preferences, directions: directions, avoiding: [])
    expect(ieltsPlan.allSatisfy { $0.track == .ielts && $0.kind != .excerpt }, "IELTS-only mode uses genuine sample references without claiming translation past papers")
    preferences.examTrack = .cet6
    expect(ExamLibrary.plan(preferences: preferences, directions: directions, avoiding: []).allSatisfy { $0.track == .cet6 }, "CET-only mode cannot silently switch track")
    preferences.topic = "财经"
    expect(ExamLibrary.plan(preferences: preferences, directions: directions, avoiding: []).allSatisfy { $0.material == nil || $0.material!.topics.contains("财经") }, "reference selection respects the chosen topic")
    preferences = Preferences()
    func rejected(_ items: [GeneratedSentence]) {
        do { _ = try ExamLibrary.assemble(plan: plan, generated: items, preferences: preferences, model: "test"); expect(false, "invalid generated slots accepted") } catch { checks += 1 }
    }
    rejected(Array(generated.dropLast()))
    var bad = generated; bad[1].slot = 1; rejected(bad)
    bad = generated; bad[1].slot = 99; rejected(bad)
    bad = generated; bad[0].direction = .zhToEn; rejected(bad)
    bad = generated; bad[0].source = String(repeating: "This is too long. ", count: 20); rejected(bad)
    bad = generated; bad[2].source = bad[0].source; rejected(bad)
    let forged = #"{"slot":2,"source":"学校应鼓励学生在实践中独立解决问题。","direction":"zhToEn","focus":"建议与实践","kind":"excerpt","year":"2026","url":"https://fabricated.example/paper"}"#
    let item = try! JSONPayload.decode(GeneratedSentence.self, from: forged)
    var honest = generated; honest[1] = item
    let assembled = try! ExamLibrary.assemble(plan: plan, generated: honest, preferences: preferences, model: "test")
    expect(assembled[2].verifiedProvenance?.kind == .original && assembled[2].citationURL == nil, "model-supplied labels, years and URLs have no authority")
    let folder = FileManager.default.temporaryDirectory.appendingPathComponent("TranslateGap-provenance-" + UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: folder) }
    let fake = FakeTutor(); let store = TutorStore(folder: folder, api: fake, keyAvailable: true)
    let old = Attempt(exercise: oldExercise, answer: "Legacy answer", assessment: FakeTutor.legacyGrade, revision: false, model: "test")
    let current = Attempt(exercise: values[0], answer: "Current answer", assessment: FakeTutor.grade, revision: false, model: "test", rubric: "2.0")
    store.state.current = oldExercise; store.state.draft = "未完成的译文"; store.state.attempts = [old, current]
    store.state.queue = values; store.flush()
    let oldIDs = store.state.attempts.map(\.id), oldCurrent = store.state.current!.id
    store.state.preferences.examTrack = .ielts; store.preferencesChanged()
    for _ in 0..<100 { if !store.generating { break }; try? await Task.sleep(nanoseconds: 5_000_000) }
    expect(store.state.current?.id == oldCurrent && store.state.draft == "未完成的译文" && store.state.attempts.map(\.id) == oldIDs, "changing examination track preserves active sentence, draft and all records")
    expect(store.state.queue.allSatisfy { $0.profile == store.state.preferences.profile }, "track changes replace stale future cache only")
    let csv = store.exportCSV()
    expect(csv.contains("source_kind,exam_track,material_id,source_title,source_url,source_locator") && csv.contains("来源未标注") && csv.contains("真题节选") && csv.contains(plan[0].material!.url), "CSV distinguishes legacy, genuine and referenced provenance")
    store.flush(); let restored = TutorStore(folder: folder, api: fake, keyAvailable: true)
    expect(restored.state.attempts.count == 2 && restored.state.attempts[0].assessment.maximumScore == 10 && restored.state.attempts[1].exercise.verifiedProvenance?.kind == .excerpt, "old and new records survive source metadata migration")
    store.cancelTasks(); restored.cancelTasks()
    print("EXAM_SOURCE_TEST_OK: \(checks) checks; catalog, exact excerpts, anti-forgery, direction, samples, old records, cache migration and CSV")
    return checks
}

@MainActor func runExamLiveTest(destination: String, key: String?) async {
    do {
        let folder = URL(fileURLWithPath: destination); try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let api = DeepSeek(keyProvider: { key ?? KeyStore.read() })
        api.generationTrace = { try? Data($0.utf8).write(to: folder.appendingPathComponent("generation-response.json")) }
        api.assessmentTrace = { try? Data($0.utf8).write(to: folder.appendingPathComponent("grading-response.json")) }
        let result = try await api.generate(preferences: Preferences(), directions: [.zhToEn, .enToZh, .zhToEn, .enToZh], avoiding: [])
        guard result.value.count == 4, result.value.allSatisfy({ $0.verifiedProvenance != nil }), Set(result.value.compactMap { $0.verifiedProvenance?.kind.rawValue }) == Set(["excerpt", "adapted", "original"]) else { throw AppFailure.message("真实接口题源分类验证未通过。") }
        let assessment = try await api.assess(exercise: result.value[0], answer: "Bamboo grows in many parts of China and comes in many varieties.", model: "deepseek-flash")
        guard assessment.value.valid, assessment.value.score >= 90 else { throw AppFailure.message("真题单句的合理译法评分未通过。") }
        let report: [String: Any] = ["requests": 2, "catalogEntries": ExamLibrary.materials.count, "classes": result.value.map { $0.sourceBadge }, "exercises": String(data: try JSONEncoder().encode(result.value), encoding: .utf8)!, "sampleScore": assessment.value.score, "grade": String(data: try JSONEncoder().encode(assessment.value), encoding: .utf8)!, "userProgressWritten": false, "keyIncluded": false]
        try JSONSerialization.data(withJSONObject: report, options: [.sortedKeys, .prettyPrinted]).write(to: folder.appendingPathComponent("exam-live-verification.json"))
        print("EXAM_LIVE_OK: 4 sentences with 3 trustworthy source classes; source-aware grade \(assessment.value.score)/100; 2 API calls; no user state written")
    } catch { fputs("EXAM_LIVE_FAILED: \(error.localizedDescription)\n", stderr); exit(1) }
}
